"""Generate an explicit, reviewable dossier from the active editable banks."""
import pathlib,json
ROOT=pathlib.Path(__file__).resolve().parents[1];r=ROOT/'web/coleccion-juridica';c=json.loads((r/'catalog.json').read_text());out=ROOT/'docs/coleccion'
lines=['# Dossier jurídico — 60 casos para revisión','', 'Fecha de comprobación documental: 2 de noviembre de 2026. Estado de todos los casos: **revisión jurídica humana pendiente**. No se atribuye revisión del letrado ni de vLex Vincent. Se trata de supuestos ficticios y contenido provisional, fuera de producción.','', '## Puntos concretos que requieren criterio del despacho','', '- Sucesiones 02, 06, 08 y 09: uso en comunidad hereditaria, efectos de repudiación, transmisión y alcance probatorio del reparto verbal. Se evita fijar indemnizaciones o resultados sin hechos. Confirmar que el alcance de Derecho civil común resulta suficiente para el público destinatario.','- Familia 02, 05, 07 y 09: interés del menor, vivienda familiar, traslado de residencia y alimentos tras la mayoría de edad. No hay soluciones automáticas ni predicción de una medida judicial.','- Vivienda 01, 07, 08 y 09: calificación del destino real, régimen temporal del desistimiento tras la reforma de octubre de 2026, subrogación tras venta y actualización sin pacto. Revisar al lanzar cualquier reforma o medida temporal; no se declara Tenerife zona tensionada ni se calcula una subida.','- Consumo 03, 04, 08 y 10: conformidad, personalización real, prueba en caídas y cómputo de prescripción de daños. No se promete devolución ni indemnización y se distinguen compras a particulares.','- Penal 06, 08, 09 y 10: requisitos del art. 197.7, apropiación frente a deuda, vigencia de prohibición y asistencia en delito leve con máximo de multa de seis meses. No se incluyen instrucciones evasivas ni garantías de condena o recuperación.','- Extranjería 05, 06, 08 y 09: régimen de familiares de españoles del RD 1155/2024, cita frente a presentación, silencio por procedimiento y garantías del expediente sancionador. No se predice expulsión ni se incluyen vías de regularización no comprobadas.','', '## Fuentes oficiales','']
for s in c['sources'].values():lines.append(f"- [{s['name']}]({s['url']})")
summary=['# Fuentes jurídicas de la colección','', 'Comprobación documental: 2 de noviembre de 2026. Once normas oficiales del BOE, incluyendo la normativa estatal de extranjería y procedimiento. Sin jurisprudencia ni revisiones de Vincent atribuidas.','', 'Los estados HTTP, tamaños y hashes están en `fuentes-verificadas.json`. `articulos-comprobados.json` localiza referencias; no acredita por sí solo una interpretación ni revisión jurídica humana. El dossier completo de los 60 casos y los puntos a revisar están en `DOSSIER-JURIDICO.md`.','']
for s in c['sources'].values():summary.append(f"- [{s['name']}]({s['url']})")
for meta in c['games']:
 g=json.loads((r/'data'/f"{meta['slug']}.json").read_text());lines+=['',f"## {g['title']} — {g['area']}",'',g['intro']];summary+=['',f"## {g['title']}",'','| Caso | Fundamento |','| --- | --- |']
 for i,q in enumerate(g['questions']):
  refs='; '.join(c['sources'][ref['source']]['name']+', '+('art. ' if not ref['articles'].startswith('disposición') else '')+ref['articles'] for ref in q['references'])
  summary.append(f"| {i+1}. {q['title']} | {refs} |")
  lines+=['',f"### {i+1}. {q['title']}",'',f"Ámbito: {q['territory']}. Comprobación: {q['verifiedDate']}. Dificultad: {q['difficulty']}/3. Revisión humana: pendiente.",'',q['situation'],'']
  for n,o in enumerate(q['options']):lines.append(f"- {chr(65+n)}. {o}"+(' **[Respuesta defendible]**' if n==q['correct'] else ''))
  lines+=['','Explicación: '+q['explanation'],'','Matiz: '+q['nuance'],'','Fundamento: '+refs+'.','', 'Consulta relacionada: '+q['consult']+'.']
(out/'DOSSIER-JURIDICO.md').write_text('\n'.join(lines)+'\n');(out/'FUENTES.md').write_text('\n'.join(summary)+'\n');print('Dossier de 60 casos y listado de fuentes generados')
